local function __cnTranslate(text)
    if type(text) ~= "string" or text == "" then return text end
    local exact = __CN_TRANSLATIONS[text]
    if exact then return exact end
    local out = text
    for _, pair in ipairs(__CN_PHRASES) do
        local from, to = pair[1], pair[2]
        local startAt = 1
        while true do
            local firstPos, lastPos = string.find(out, from, startAt, true)
            if not firstPos then break end
            out = string.sub(out, 1, firstPos - 1) .. to .. string.sub(out, lastPos + 1)
            startAt = firstPos + #to
        end
    end
    return out
end

local function __cnApply(obj)
    pcall(function()
        if obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox") then
            local translated = __cnTranslate(obj.Text)
            if translated ~= obj.Text then obj.Text = translated end
        end
        if obj:IsA("TextBox") then
            local translatedPlaceholder = __cnTranslate(obj.PlaceholderText)
            if translatedPlaceholder ~= obj.PlaceholderText then obj.PlaceholderText = translatedPlaceholder end
        end
    end)
end

task.spawn(function()
    local Players = game:GetService("Players")
    local CoreGui = game:GetService("CoreGui")
    local LocalPlayer = Players.LocalPlayer
    local connectedRoots = setmetatable({}, { __mode = "k" })
    local function scan(root)
        if not root then return end
        for _, obj in ipairs(root:GetDescendants()) do
            __cnApply(obj)
        end
        if connectedRoots[root] then return end
        connectedRoots[root] = true
        root.DescendantAdded:Connect(function(obj)
            task.wait(0.05)
            __cnApply(obj)
        end)
    end
    pcall(function() scan(CoreGui) end)
    pcall(function() scan(LocalPlayer:WaitForChild("PlayerGui", 10)) end)
    while true do
        pcall(function() scan(CoreGui) end)
        pcall(function() scan(LocalPlayer:FindFirstChild("PlayerGui")) end)
        task.wait(1)
    end
end)

